<script>
(() => {
  const money = (value) => new Intl.NumberFormat(document.body.dataset.lang === 'en' ? 'en-IE' : 'pt-PT', { style: 'currency', currency: 'EUR' }).format(value || 0);
  const key = 'maison_boulangerie_bag_v2';
  const labels = { empty: <?= json_encode($t['emptyBag'], JSON_UNESCAPED_UNICODE) ?>, added: <?= json_encode($t['add'], JSON_UNESCAPED_UNICODE) ?> };
  const getBag = () => { try { return JSON.parse(localStorage.getItem(key) || '[]'); } catch(e) { return []; } };
  const setBag = (bag) => { localStorage.setItem(key, JSON.stringify(bag)); renderBag(); };
  const subtotal = (bag) => bag.reduce((sum, item) => sum + (Number(item.price) * Number(item.qty || 1)), 0);
  const toast = document.querySelector('[data-toast]');
  function showToast(text) { if (!toast) return; toast.textContent = text; toast.classList.add('show'); setTimeout(() => toast.classList.remove('show'), 1700); }
  function addItem(item) { const bag = getBag(); const found = bag.find(x => x.slug === item.slug); if (found) found.qty += 1; else bag.push({ ...item, qty: 1 }); setBag(bag); showToast(item.name + ' · ' + labels.added); }
  function changeQty(slug, delta) { const bag = getBag().map(item => item.slug === slug ? { ...item, qty: Math.max(0, Number(item.qty) + delta) } : item).filter(item => item.qty > 0); setBag(bag); }
  function itemHtml(item) { return `<div class="bag-item"><img src="${item.image}" alt=""><div><h4>${item.name}</h4><small>${money(Number(item.price))}</small><div class="qty"><button type="button" data-qty="${item.slug}" data-delta="-1">−</button><strong>${item.qty}</strong><button type="button" data-qty="${item.slug}" data-delta="1">+</button></div></div><strong>${money(Number(item.price) * Number(item.qty))}</strong></div>`; }
  function renderBag() {
    const bag = getBag(); const count = bag.reduce((s,i)=>s+Number(i.qty||1),0); const sub = subtotal(bag);
    document.querySelectorAll('[data-bag-count]').forEach(el => el.textContent = count);
    document.querySelectorAll('[data-bag-items], [data-page-bag]').forEach(el => { el.innerHTML = bag.length ? bag.map(itemHtml).join('') : `<p class="status-note">${labels.empty}</p>`; });
    document.querySelectorAll('[data-drawer-subtotal], [data-page-subtotal]').forEach(el => el.textContent = money(sub));
    document.querySelectorAll('[data-page-total]').forEach(el => el.textContent = money(sub ? sub + 3.5 : 0));
    const receipt = document.getElementById('checkoutReceipt');
    if (receipt) { receipt.innerHTML = (bag.length ? bag.map(i => `<div class="receipt-line"><span>${i.qty}× ${i.name}</span><strong>${money(Number(i.price)*Number(i.qty))}</strong></div>`).join('') : `<p class="status-note">${labels.empty}</p>`) + `<div class="receipt-line"><span><?= e($t['delivery']) ?></span><strong>${money(bag.length ? 3.5 : 0)}</strong></div><div class="receipt-line total"><span><?= e($t['total']) ?></span><strong>${money(bag.length ? sub + 3.5 : 0)}</strong></div>`; }
  }
  document.addEventListener('click', (event) => {
    const add = event.target.closest('[data-add]'); if (add) { addItem(JSON.parse(add.dataset.add)); }
    const qty = event.target.closest('[data-qty]'); if (qty) { changeQty(qty.dataset.qty, Number(qty.dataset.delta)); }
    if (event.target.closest('[data-open-bag]')) document.querySelector('[data-drawer]')?.classList.add('open');
    if (event.target.closest('[data-close-bag]')) document.querySelector('[data-drawer]')?.classList.remove('open');
    const filter = event.target.closest('[data-filter]'); if (filter) { document.querySelectorAll('[data-filter]').forEach(b=>b.classList.remove('active')); filter.classList.add('active'); const value = filter.dataset.filter; document.querySelectorAll('[data-category]').forEach(row => row.classList.toggle('hide', value !== 'all' && row.dataset.category !== value)); }
    const gf = event.target.closest('[data-gallery-filter]'); if (gf) { document.querySelectorAll('[data-gallery-filter]').forEach(b=>b.classList.remove('active')); gf.classList.add('active'); const value = gf.dataset.galleryFilter; document.querySelectorAll('[data-gallery-cat]').forEach(row => row.classList.toggle('hide', value !== 'all' && row.dataset.galleryCat !== value)); }
  });
  renderBag();
})();
</script>
</body>
</html>
